describe('promise AbortSignal configuration',()=>{for(const convert of [firstValueFrom,lastValueFrom]){
 checked('rejects pre-aborted calls without subscribing',async()=>{const c=new AbortController();c.abort();let subscribed=0;const source=new Observable<number>(()=>{subscribed++;});let error:any;try{await bounded(convert(source,{defaultValue:9,signal:c.signal} as any));}catch(e){error=e;}expect(error?.name).to.equal('AbortError');expect(subscribed).to.equal(0);});
