 checked('preserves natural values and default completion',async()=>{const c=new AbortController();expect(await convert(of(1),{defaultValue:9,signal:c.signal} as any)).to.equal(1);expect(await convert(EMPTY,{defaultValue:9,signal:c.signal} as any)).to.equal(9);c.abort();});
