const assert=require('node:assert/strict');const {test}=require('node:test');const _=require('../lodash.js');
test('opt-in own enumerable symbols follow string keys',()=>{const s=Symbol('s'),o={a:1,[s]:2};assert.deepEqual(_.keys(o),['a']);assert.deepEqual(_.values(o),[1]);assert.deepEqual(_.keys(o,{symbols:true}),['a',s]);assert.deepEqual(_.values(o,{symbols:true}),[1,2]);});
test('exclude inherited and nonenumerable symbols',()=>{const inherited=Symbol('i'),hidden=Symbol('h'),own=Symbol('o'),o=Object.create({[inherited]:3});o.a=1;o[own]=2;Object.defineProperty(o,hidden,{value:4});assert.deepEqual(_.keys(o,{symbols:true}),['a',own]);assert.deepEqual(_.values(o,{symbols:true}),[1,2]);});
test('arrays keep ordinary index behavior and append own symbols',()=>{const s=Symbol('a'),o=[10,20];o[s]=30;assert.deepEqual(_.keys(o,{symbols:true}),['0','1',s]);assert.deepEqual(_.values(o,{symbols:true}),[10,20,30]);});
test('false/null options and null inputs retain defaults',()=>{for(const option of [undefined,null,false,{symbols:false},{symbols:1}]){const s=Symbol(),o={a:1,[s]:2};assert.deepEqual(_.keys(o,option),['a']);assert.deepEqual(_.values(o,option),[1]);}for(const o of [null,undefined]){assert.deepEqual(_.keys(o,{symbols:true}),[]);assert.deepEqual(_.values(o,{symbols:true}),[]);}});
test('inherited APIs are unaffected',()=>{const s=Symbol(),o=Object.create({p:1});o.a=2;o[s]=3;assert.deepEqual(_.keysIn(o),['a','p']);assert.deepEqual(_.valuesIn(o),[2,1]);});
